import { ActionDefinition } from '../../../Action'
import {
    TableNameColumn,
    ReferenceColumn,
    BooleanColumn,
    DocumentIdColumn,
    ConditionsColumn,
    ChoiceColumn,
    DurationColumn,
} from '../../../../db'

export const waitForCondition = ActionDefinition({
    $id: '89ce8a4187120010663ca1bb36cb0be3',
    name: 'Wait For Condition',
    description:
        'Wait for condition action causes the flow to wait until the record matches the specified condition. Use this activity to block the flow indefinitely until a particular condition is met. You must populate the condition field.',
    inputs: {
        timeout_duration: DurationColumn({
            label: 'Duration',
        }),
        table_name: TableNameColumn({
            label: 'Table',
        }),
        timeout_schedule: ReferenceColumn({
            label: 'Schedule',
            maxLength: 8000,
            referenceTable: 'cmn_schedule',
        }),
        timeout_flag: BooleanColumn({
            label: 'Enable timeout',
        }),
        record: DocumentIdColumn({
            label: 'Record',
            dependent: 'table_name',
            mandatory: true,
        }),
        conditions: ConditionsColumn({
            label: 'Conditions',
            mandatory: true,
        }),
    },
    outputs: {
        state: ChoiceColumn({
            label: 'State',
            maxLength: 32,
            default: '0',
            choices: {
                0: {
                    label: 'Complete',
                },
                1: {
                    label: 'Timeout',
                    sequence: 1,
                },
            },
        }),
    },
})
